  "code": "import re\n\n\ndef rule_majority_opinion_header(doc: dict) -> list[dict]:\n    try:\n        def norm(text: str) -> str:\n            return re.sub(r\"\\s+\", \" \", (text or \"\")).strip()\n\n        def with_meta(item: dict) -> dict:\n            span = {\"text\": (item.get(\"text\") or \"\").strip()}\n            for key in (\"page_no\", \"line_no\", \"paragraph_no\"):\n                if key in item:\n                    span[key] = item[key]\n            return span\n\n        header_re = re.compile(\n            r\"\\b(?:Amended\\s+)?Opinion by Judge\\b|\\bPer Curiam Opinion\\b|\\bPer Curiam\\b\",\n            re.IGNORECASE,\n        )\n\n        for key in (\"lines\", \"paragraphs\", \"pages\"):\n            items = [item for item in (doc.get(key) or []) if isinstance(item, dict)]\n            for idx, item in enumerate(items[:120]):\n                text = norm(item.get(\"text\"))\n                if not text:\n                    continue\n                if header_re.search(text):\n                    if \"per curiam\" in text.lower():\n                        for look_idx, look_ahead in enumerate(items[idx + 1 : idx + 8], start=1):\n                            look_text = norm(look_ahead.get(\"text\"))\n                            if not look_text:\n                                continue\n                            if \"judge\" in look_text.lower() and (\n                                \"drafting\" in look_text.lower()\n                                or \"participation\" in look_text.lower()\n                                or \"passed away\" in look_text.lower()\n                            ):\n                                for back_idx in (look_idx - 1, look_idx - 2):\n                                    if back_idx <= 0:\n                                        continue\n                                    prev = items[idx + back_idx]\n                                    prev_text = norm(prev.get(\"text\"))\n                                    if (\n                                        \"judge\" in prev_text.lower()\n                                        and \"passed away\" in prev_text.lower()\n                                    ):\n                                        return [with_meta(prev)]\n                                return [with_meta(look_ahead)]\n                    return [with_meta(item)]\n\n        full_text = doc.get(\"text\") or \"\"\n        m = re.search(\n            r\"\\b(?:Amended\\s+)?Opinion by Judge\\b[^\\n;]*\",\n            full_text,\n            flags=re.IGNORECASE,\n        )\n        if m:\n            return [{\"text\": m.group(0).strip()}]\n\n        m = re.search(r\"\\bPer Curiam Opinion\\b\", full_text, flags=re.IGNORECASE)\n        if m:\n            return [{\"text\": m.group(0).strip()}]\n\n        m = re.search(r\"^\\s*Per Curiam\\s*$\", full_text, flags=re.IGNORECASE | re.MULTILINE)\n        if m:\n            return [{\"text\": m.group(0).strip()}]\n\n        return []\n    except Exception:\n        return []\n",
